-- KB-028 user/workspace revocation, stale role, delegated key, approval and delayed queued authority.
-- Additive candidate semantic correction. No changes to historical customer assessments, security findings, existing evidence or deployment decisions.
UPDATE risk_knowledge_entries SET problem_json='{"statement":"Deprovisioning, role changes or workspace removal do not terminate active sessions, keys, approvals or queued actions.","customer_symptom":"A removed workspace user or demoted role continues privileged agent, tool or queued actions with a stale session, key, cache or approval.","credible_failure_or_attack":"Previously issued sessions, delegated credentials, cached ACL decisions, approval grants or queued jobs are accepted after deprovisioning or role downgrade because receiving services fail to reauthorize current user/workspace identity.","affected_assets":["workspace membership and authoritative roles","sessions and delegated credentials","approval grants and cached authorization","queued, retried and scheduled agent/tool actions","tenant records and downstream effects","revocation propagation and audit events"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["enterprise workspaces"],"threat_actor_or_failure_source":"removed user, stale delegated identity, revoked role, invalidation failure, cached authorization or asynchronous job worker","trust_boundary":"Between current authoritative user/workspace roles and receiving-side enforcement of each session, key, cache, approval, job or tool action. Authentication of a formerly valid token does not confer current authority.","operational_impact":"An invalidated principal may continue accessing tenant records or triggering privileged side effects. Containment requires dependent-session and approval revocation, queue isolation, correlated evidence and accountable retest."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-11","next_review_due":"2026-12-10","change_triggers":["ARL-KB-028 user lifecycle, role, workspace-membership or deprovisioning change","ARL-KB-028 session, key, approval, queue or delayed-execution revocation change","ARL-KB-028 continued access after role removal or deprovisioning incident","ARL-KB-028 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"candidate semantic correction; independent practitioner and customer validation required"}', content_digest='9a239967cf149448fc09b7e5e0591c786ee34eb5edb11ce7c391ec47928b7d6b', updated_at='2026-10-11' WHERE id='ARL-KB-028';
UPDATE risk_knowledge_checks SET objective='Determine whether user removal, role downgrade and deprovisioning invalidate or reauthorize derived sessions, keys, cached roles, approvals and deferred agent/tool actions within a documented revocation effective time and propagation bound.', method='Bind the exact assessed build, environment and scope. Inspect owner-approved revocation policy and receiving-side session, delegated-key, role-cache, approval and queued-work controls. With separate written owner authorization and synthetic staging identities, execute bounded positive current-role operations and negative replay after role removal, account disablement, approval withdrawal or key revocation. Correlate revocation timestamp, documented propagation cutoff, receiver decisions and downstream effects. ARL never assumes instantaneous revocation or creates a security finding from missing traces.', required_evidence_json='["ARL-KB-028 assessed system, exact version, environment and applicable user, workspace, role, session, key, approval, cache, job and tool scope","ARL-KB-028 organisation-approved revocation policy, effective cutoff, propagation latency and accountable identity owner","ARL-KB-028 source or configuration evidence of receiving-side current-role enforcement, session and key invalidation, approval withdrawal, cached ACL freshness and job reauthorization","ARL-KB-028 bounded positive evidence of permitted current-role and post-downgrade synthetic user, agent and tool operations","ARL-KB-028 bounded negative evidence of removed members, revoked sessions or keys, stale approvals, cached elevated roles and queued or retried work denied after approved cutoff before unauthorized effects","ARL-KB-028 observed runtime correlation of revocation event, effective timestamp, propagation, identity and role at receiver, policy decision and downstream side effects","ARL-KB-028 reviewer identity, written testing authorization, roles, timestamp, assessed version, evidence digest, untested paths, grace periods and accountable decision"]', pass_condition='KB-028 passes only after accountable human review of the exact assessed version, current-role positive paths, synthetic negative replays of stale sessions, keys, roles, approvals and jobs, observed denial before unauthorized effects after the owner-approved revocation cutoff, measured propagation and corroborated downstream traces across applicable paths.', fail_condition='KB-028 is a confirmed FAIL only where reproducible exact-version evidence demonstrates unauthorized disclosure, tool execution or state change after the approved revocation cutoff, or receiver-side acceptance of explicitly invalidated authority. Missing source, policy, approved cutoff, negative tests, runtime observations, assessed-version binding or reviewer decision requires INCONCLUSIVE / EVIDENCE GAP / REVIEW REQUIRED: block PASS and deployment without inventing a confirmed vulnerability.', limitations='This bounded test does not prove absence of undiscovered paths or future regressions. Document owner-approved revocation grace period, measured propagation and untested downstream surfaces; no legal conclusion or deployment permission is inferred.', content_digest='43037bde64334f134f0f3451aca1514365cc94fc0aaab659046a3ad74674e77e', updated_at='2026-10-11' WHERE entry_id='ARL-KB-028';
UPDATE risk_knowledge_solutions SET control_objective='Invalidate or reauthorize all derived user/workspace authority at sessions, delegated keys, approval caches, background workers and downstream tools within a documented revocation propagation bound.', recommended_remediation='Bind authority to current user, workspace and role state; invalidate dependent sessions and delegated keys, withdraw approvals, expire role caches, cancel or reauthorize queued work and retry paths before executing tools. Record effective times, propagation latency and correlated denial/effect traces.', implementation_principles_json='["ARL-KB-028: Bind active sessions, delegated keys and approvals to current authoritative workspace membership and role.","ARL-KB-028: Track effective revocation timestamp and owner-approved propagation bound; invalidate caches and tokens within that bound.","ARL-KB-028: Reauthorize queued and retried high-impact operations at the receiving service immediately before their side effects.","ARL-KB-028: Preserve redacted correlated identity, revocation, receiver decisions and downstream effects; never rely on model instructions for enforcement."]', monitoring='Monitor revocation timestamp, propagated identity/session/key/role cache/approval/job invalidation, delayed action attempts, policy digest, receiver authorization and downstream side effects. Alert on authorization after approved cutoff.', containment='Suspend affected user/delegated identities, revoke sessions and keys, withdraw approvals, isolate privileged tool queues, preserve exact-version traces and require accountable verification before re-enablement.', retest_acceptance_json='["ARL-KB-028: Versioned owner-approved revocation policy, identity routes, approved propagation latency and exact remediated build are recorded.","ARL-KB-028: Synthetic current-role and post-downgrade permitted actions complete with expected authorized outputs.","ARL-KB-028: Old sessions, keys, cached roles, approvals, retries and queued jobs are denied after approved cutoff before unauthorized data or effects with correlated receiver/downstream audit evidence.","ARL-KB-028: Reviewer records authorized scope, tester roles, timestamps, observed propagation, evidence digests, unsupported paths and final accountable decision."]', content_digest='d387f8e346d052ed935a7bd8288c967c1c9aa085497aafe89b7de71e24fc8305', updated_at='2026-10-11' WHERE entry_id='ARL-KB-028';
UPDATE risk_knowledge_entry_classification SET review_date='2026-10-11', updated_at='2026-10-11' WHERE entry_id='ARL-KB-028';
